<https://example.org/openevidence/questions/q_epilepsy_efficacy> a holon:ClinicalQuestionHolon ;
    oe:questionText "How effective is levetiracetam compared with other agents for Epilepsy?"^^xsd:string ;
    oe:answerText "To determine the efficacy and safety of clobazam, a benzodiazepine derivative endorsed for adjunctive therapy in drug-resistant epilepsy due to its broad-spectrum efficacy and tolerability profile, as an adjunctive treatment for pediatric patients with drug-resistant epilepsy. This was a multicenter, real-world, self-controlled study."^^xsd:string ;
    oe:belongsToSpecialty "Neurology" ;
    holon:hasInteriorGraph <https://example.org/openevidence/questions/q_epilepsy_efficacy-int> ;
    holon:hasBoundaryGraph <https://example.org/openevidence/questions/q_epilepsy_efficacy-bou> ;
    holon:hasProjectionGraph <https://example.org/openevidence/questions/q_epilepsy_efficacy-pro> ;
    holon:hasContextGraph <https://example.org/openevidence/questions/q_epilepsy_efficacy-con> ;
    holon:evidenceQualityThreshold "0.50"^^xsd:decimal .

